Base.@kwdef struct DecimalType
    scale::Int32  # 1: required i32 scale
    precision::Int32  # 2: required i32 precision
    unknown_fields::Vector{Thrift.RawField} = Thrift.RawField[]
end

function Base.:(==)(a::DecimalType, b::DecimalType)
    return a.scale == b.scale && a.precision == b.precision && a.unknown_fields == b.unknown_fields
end

function Base.isequal(a::DecimalType, b::DecimalType)
    return isequal(a.scale, b.scale) && isequal(a.precision, b.precision) && isequal(a.unknown_fields, b.unknown_fields)
end

function Base.hash(x::DecimalType, h::UInt)
    h = hash(:DecimalType, h)
    h = hash(x.scale, h)
    h = hash(x.precision, h)
    h = hash(x.unknown_fields, h)
    return h
end

function Thrift.typecode(::Core.Type{DecimalType})
    return Thrift.STRUCT
end

function Thrift.readelement(r::Thrift.Reader, ::Core.Type{DecimalType})
    return Thrift.decode(r, DecimalType)
end

function Thrift.writeelement!(w::Thrift.Writer, x::DecimalType)
    Thrift.encode!(w, x)
    return
end

function Thrift.decode(r::Thrift.Reader, ::Core.Type{DecimalType})
    Thrift.enter!(r)
    f_scale = nothing
    f_precision = nothing
    unknown = nothing
    lastid = Int16(0)
    while true
        id, ty = Thrift.readfieldheader(r, lastid)
        ty == Thrift.STOP && break
        lastid = id
        if id == Int16(1) && ty == Thrift.I32
            f_scale = Thrift.readi32(r)
        elseif id == Int16(2) && ty == Thrift.I32
            f_precision = Thrift.readi32(r)
        else
            unknown = Thrift.pushunknown!(unknown, Thrift.readrawfield(r, id, ty))
        end
    end
    Thrift.leave!(r)
    unknown_fields = Thrift.finishunknown(r, unknown)
    f_scale === nothing && Thrift.missingfield(:DecimalType, :scale)
    f_precision === nothing && Thrift.missingfield(:DecimalType, :precision)
    return DecimalType(f_scale, f_precision, unknown_fields)
end

function Thrift.encode!(w::Thrift.Writer, x::DecimalType)
    unknown = x.unknown_fields
    lastid = Int16(0)
    index = 1
    (lastid, index) = Thrift.writeunknownafter!(w, unknown, index, lastid)
    lastid = Thrift.writefieldheader!(w, lastid, Int16(1), Thrift.I32)
    Thrift.writei32!(w, x.scale)
    (lastid, index) = Thrift.writeunknownafter!(w, unknown, index, lastid)
    lastid = Thrift.writefieldheader!(w, lastid, Int16(2), Thrift.I32)
    Thrift.writei32!(w, x.precision)
    (lastid, index) = Thrift.writeunknownafter!(w, unknown, index, lastid)
    Thrift.writeunknownrest!(w, unknown, index, lastid)
    Thrift.writestop!(w)
    return
end

